CREATE TABLE career_fact (id BIGINT NOT NULL AUTO_INCREMENT,profile_id BIGINT NOT NULL,fact_type VARCHAR(64) NOT NULL,fact_key VARCHAR(128) NOT NULL,value_type VARCHAR(16) NOT NULL,boolean_value TINYINT DEFAULT NULL,number_value DECIMAL(12,2) DEFAULT NULL,text_value VARCHAR(1000) DEFAULT NULL,unit VARCHAR(32) DEFAULT NULL,display_name VARCHAR(255) NOT NULL,source VARCHAR(32) NOT NULL DEFAULT 'USER_CONFIRMED',confirmed_at DATETIME DEFAULT NULL,created_at DATETIME DEFAULT NULL,updated_at DATETIME DEFAULT NULL,PRIMARY KEY(id),UNIQUE KEY uk_career_fact_profile_key(profile_id,fact_type,fact_key),KEY idx_career_fact_profile(profile_id));
